"""Compile a validated leaf pair into attributed parent input, without inventing coverage."""
import hashlib,json,sys
from pathlib import Path
B=Path(__file__).resolve().parent;F=B.parent;E=F.parent;C=F/'compact-v1';sys.path.insert(0,str(C));from compact_pipeline import dump,hfile

def content_id(kind,definition):return 'q025-candidate-'+kind+':'+hashlib.sha256(json.dumps({'kind':kind,'question':definition['question'],'scope':definition['scope']},ensure_ascii=False,separators=(',',':'),sort_keys=True).encode()).hexdigest()[:24]
def build(jobdir,region,members):
 jobdir=Path(jobdir);receipt=json.loads((jobdir/'receipt.json').read_text());assert receipt['status']=='complete' and not receipt.get('toolUseAttempted');reply=json.loads((jobdir/'reply.json').read_text());packet_path=jobdir/('packet.actual.json' if (jobdir/'packet.actual.json').exists() else 'packet.json');packet=json.loads(packet_path.read_text());assert reply['stage']=='challenge';assert len(reply['units'])==len(packet['units']);uids={u['i']:packet['refRegistry'][f'u{u["i"]}']['unitId'] for u in packet['units']};assessed={uids[a['i']] for a in reply['units']};eligible=set(members['eligibleDescriptionIds']);sealed=set(members['reservedUnreviewedIds']);assert not sealed&assessed
 if packet.get('kind')=='parent':
  assert sum(c['reviewedDescriptionCount'] for c in packet['childScopes'])==len(eligible),'Inherited description coverage is incomplete'
  assert sum(c['fullMemberCount'] for c in packet['childScopes'])==len(members['candidateMemberIds']),'Child original coverage mismatch'
 else:assert eligible<=assessed
 if receipt.get('normalizedReplySha256'):assert hfile(jobdir/'reply.json')==receipt['normalizedReplySha256']
 if receipt.get('normalizationReceiptSha256'):assert hfile(jobdir/'normalization.json')==receipt['normalizationReceiptSha256']
 reviews={a['id']:a for a in reply['cardReviews']};prior={a['id']:a for a in packet['priorCards']};assert 'r' in reviews and 'r' in prior
 supported=lambda a:a['decision']=='supported_as_written' and a['scopeChange']=='same'
 region_supported=supported(reviews['r']);definition=prior['r'] if region_supported else reply['region'];region_def={k:definition[k] for k in ['title','question','summary','scope','readingLimit']};questions=[]
 for ref,c in prior.items():
  if ref=='r' or ref.startswith('c'):continue
  a=reviews[ref];questions.append({'candidateId':content_id('question',c),'localRef':ref,'scopeStatus':'independently_supported' if supported(a) else 'unresolved_scope_change','definition':{k:c[k] for k in ['title','question','summary','scope','readingLimit']},'assessment':a,'sourceUnitIds':[uids[x['i']] for x in reply['units'] if any(q['id']==ref for q in x['q'])]})
 for c in reply['cards']:questions.append({'candidateId':content_id('question',c),'localRef':c['id'],'scopeStatus':'new_challenger_proposal','definition':{k:c[k] for k in ['title','question','summary','scope','readingLimit']},'sourceUnitIds':[uids[x['i']] for x in reply['units'] if any(q['id']==c['id'] for q in x['q'])]})
 return {'schemaVersion':'q025-child-scope-for-parent/1','candidateRegionId':region['candidateRegionId'],'reviewKey':region['reviewKey'],'scopeCandidateId':content_id('region',region_def),'scopeStatus':'independently_supported' if region_supported else 'new_challenger_proposal','region':region_def,'regionAssessment':reviews['r'],'memberIdsSha256':hashlib.sha256('\n'.join(sorted(members['candidateMemberIds'])).encode()).hexdigest(),'fullMemberCount':len(members['candidateMemberIds']),'reviewedDescriptionCount':len(eligible),'reservedUnreviewedCount':len(sealed),'providedContrastOrMemberCount':len(reply['units']),'sourceExcerptReadCount':sum(a['b']=='excerpt' for a in reply['units']),'unresolvedAssignmentCount':sum(c['unresolvedAssignmentCount'] for c in packet['childScopes']) if packet.get('kind')=='parent' else sum(a['d'] in ['unresolved','alternate'] for a in reply['units'] if uids[a['i']] in eligible),'fineIdentityCounts':{'proposedSingleton':sum(a['identity']=='s' for a in reply['units'] if uids[a['i']] in eligible),'unresolved':sum(a['identity']=='?' for a in reply['units'] if uids[a['i']] in eligible),'newGroupCandidates':len(reply['identityGroups'])},'questions':questions,'unresolved':reply['unresolved'],'pins':{'challengeReceiptSha256':hfile(jobdir/'receipt.json'),'challengeReplySha256':hfile(jobdir/'reply.json'),'challengePacketSha256':hfile(packet_path),'normalizationSha256':hfile(jobdir/'normalization.json') if (jobdir/'normalization.json').exists() else None},'admission':'This is attributed parent input, not the global acceptance receipt; canonical equivalence and direct placements require their own decisions.'}
if __name__=='__main__':
 key=sys.argv[1];jobdir=Path(sys.argv[2]);plan=json.loads((F/'coverage-plan.json').read_text());region=next(r for r in plan['regions'] if r['reviewKey']==key);members=json.loads((F/'coverage-memberships.local.json').read_text())[key];artifact=build(jobdir,region,members);dump(sys.argv[3],artifact);print(json.dumps({'region':key,'scopeStatus':artifact['scopeStatus'],'reviewedDescriptions':artifact['reviewedDescriptionCount'],'reservedUnreviewed':artifact['reservedUnreviewedCount'],'questions':len(artifact['questions'])}))
